// Emits ONE self-contained browser script: window.GZWall = { run(personaKey, ctx) }. Paste it in a tab where the PERSONA is logged in.
// Run: node zoho/wall/build-bundle.mjs   -> /home/claude/work/sandbox-setup/bundles/wall.js
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const OUT = process.argv[2] ?? "/home/claude/work/sandbox-setup/bundles/wall.js";

export function buildBundle() {
  const core = readFileSync(join(here, "check.mjs"), "utf8").replace(/^export /gm, "");
  if (/^\s*import\s/m.test(core) || /export default/.test(core)) throw new Error("check.mjs must stay import-free");
  const expectations = readFileSync(join(here, "expectations.json"), "utf8").trim();
  return `/* GZWall: wall test for the Growize Staging sandbox. Generated by zoho/wall/build-bundle.mjs; do not edit. Read-only except a Test_Seed touch/receipt it deletes at once. */
(() => {
  "use strict";
${core}
  const EXPECTATIONS = ${expectations};
  window.GZWall = {
    /** persona: ir_a | ir_b | kam | finance_ops | compliance | admin. ctx.ownerMap optional {userId|lowercased name: personaTag}. */
    async run(persona, ctx = {}) {
      if (typeof window.__z !== "function") throw new Error("window.__z is not defined in this tab");
      const call = (m, p, b) => window.__z(m, p, b);
      await assertSandbox(call);
      if (!EXPECTATIONS.personas[persona]) throw new Error("persona must be one of " + EXPECTATIONS.personaKeys.join(", "));
      let ownerMap = ctx.ownerMap;
      if (!ownerMap) {
        const u = await call("GET", "/crm/v8/users?type=ActiveUsers&per_page=200");
        ownerMap = ownerMapFromUsers(u.body?.users, EXPECTATIONS);
      }
      const observation = await observe(call, persona, EXPECTATIONS, { ownerMap });
      const rows = evaluate(EXPECTATIONS, persona, observation);
      const summary = summarize(rows, persona);
      const table = rows.map((r) => ({ check: r.check, expected: String(r.expected), actual: String(r.actual), result: r.pass === null ? "skip" : r.pass ? "PASS" : r.advisory ? "warn" : "FAIL", traces: r.traces.join(" ") }));
      console.table(table);
      console.log("GZWall " + persona + ": " + (summary.ok ? "PASS" : "FAIL") + " " + JSON.stringify(summary));
      return { summary, table, details: rows.filter((r) => r.detail).map((r) => r.check + ": " + r.detail), observation };
    },
  };
})();
`;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  mkdirSync(dirname(OUT), { recursive: true });
  writeFileSync(OUT, buildBundle());
  console.log("wrote " + OUT);
}
